INSERT OR IGNORE INTO reading_exam_sections (id,exam_id,section_code,title,instructions,main_text,exercise_type,extra_data_json,order_index,points_max) VALUES
('pruefung-01-teil1','pruefung-01','teil1','Lesen – Teil 1','Ordnen Sie jedem Text die passende Überschrift zu. Zwei Überschriften bleiben übrig.','1. Die Stadtverwaltung verwandelt mehrere graue Bushaltestellen in kleine Klimainseln. Neue Dächer werden mit Pflanzen begrünt, speichern einen Teil des Regenwassers und spenden im Sommer Schatten. Außerdem sollen die bepflanzten Haltestellen die Luftqualität im dicht bebauten Zentrum verbessern.

2. Viele Beschäftigte versuchen, ohne Unterbrechung durchzuarbeiten. Ein Forschungsprojekt zeigt jedoch, dass kurze Bewegungspausen die Aufmerksamkeit steigern können. Schon neunzig Sekunden Aufstehen, Dehnen oder Blickwechsel reichen aus, damit sich die Konzentration nach einer längeren Arbeitsphase wieder erholt.

3. In immer mehr Stadtteilen teilen Nachbarinnen und Nachbarn Lebensmittel, die in Geschäften nicht mehr verkauft werden dürfen, obwohl sie noch genießbar sind. Die beteiligten Läden sparen Entsorgungskosten, während die Abholenden gemeinsam entscheiden, wie die Waren verteilt werden.

4. In einem Reparaturcafé bringen Bürgerinnen und Bürger kaputte Lampen, Toaster oder Radios mit. Ehrenamtliche helfen bei der Fehlersuche und zeigen, wie man einfache Reparaturen selbst durchführen kann. Bezahlt wird nur das Material; wichtiger ist der Austausch von Wissen.

5. Wer ein großes Fahrrad für Einkäufe oder den Transport von Kindern benötigt, muss es nicht unbedingt kaufen. Die Stadtbibliothek verleiht neben Büchern inzwischen auch Lastenräder. Nach einer kurzen Einweisung können registrierte Nutzerinnen und Nutzer die Räder für mehrere Tage reservieren.','matching_titles','{"source":"original_practice_content","sourceSetId":"teil1-01","titleAr":"تغييرات صغيرة، تأثير كبير","originalSetTitle":"Kleine Veränderungen, große Wirkung","slides":[{"id":"texte","label":"Texte","type":"texts","description":"Lesen Sie die fünf kurzen Mitteilungen."},{"id":"ueberschriften","label":"Überschriften","type":"headlines","description":"Ordnen Sie jeder Mitteilung die passende Überschrift zu."}],"variantCount":3,"officialStatus":"Not official telc/Zertify","titles":[{"code":"A","text":"Lebensmittel teilen statt wegwerfen"},{"code":"B","text":"Mini-Pausen stärken die Konzentration"},{"code":"C","text":"Alte Geräte erhalten eine zweite Chance"},{"code":"D","text":"Neue Klimainseln entstehen an Haltestellen"},{"code":"E","text":"Fahrradfahren ist nur etwas für Sportler"},{"code":"F","text":"Lastenräder kann man auch ausleihen"},{"code":"G","text":"Ein Garten für alle Generationen"},{"code":"H","text":"Schnelle Lösungen für hohe Stromkosten"},{"code":"I","text":"Mehr Urlaub durch bessere Planung"},{"code":"J","text":"Wie Kinder sicher schwimmen lernen"}]}',0,25),
('pruefung-01-teil2','pruefung-01','teil2','Lesen – Teil 2','Lesen Sie den Text und wählen Sie bei jeder Aufgabe die richtige Lösung.','Auf einem früheren Parkplatz am Rand einer dicht bebauten Wohnsiedlung wächst heute ein gemeinschaftlicher Garten. Die Idee entstand während eines besonders heißen Sommers. Anwohnerinnen und Anwohner suchten einen Ort, an dem sie sich treffen konnten, ohne in einer aufgeheizten Wohnung oder auf einer betonierten Fläche zu sitzen. Die Stadt stellte das Grundstück zunächst für fünf Jahre zur Verfügung.

Die Beteiligten legten Beete an, pflanzten Bäume und bauten eine große Zisterne. Das Regenwasser von den umliegenden Dächern wird gesammelt und in trockenen Wochen zum Gießen verwendet. Für die Planung engagierten sich nicht nur Gartenexperten. Auch Kinder, ältere Menschen und Familien, die bisher kaum Kontakt miteinander hatten, übernahmen eigene Aufgaben.

Im ersten Jahr mussten die Organisatoren lernen, dass ein Garten nicht automatisch von allein funktioniert. Einige Pflanzen wurden zu dicht gesetzt, andere vertrugen die starke Sonne nicht. Außerdem fehlte anfangs ein verbindlicher Plan für das Gießen. Nach einer gemeinsamen Auswertung teilten die Gruppen die Beete neu auf und führten einen einfachen Kalender ein.

Heute ist der Garten nicht nur ein Ort für Gemüse. Im Sommer finden dort kostenlose Kochabende statt, bei denen die Ernte verarbeitet wird. Für die kommenden Jahre wünschen sich die Initiatoren ein begrüntes Dach über dem Treffpunkt und weitere Zisternen. Sie hoffen, dass das Projekt auch andere Stadtteile dazu anregt, ungenutzte Flächen gemeinsam zu verändern.','multiple_choice','{"source":"original_practice_content","sourceSetId":"teil2-01","titleAr":"حديقة تُنعش الحي","originalSetTitle":"Ein Garten, der die Nachbarschaft kühlt","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie den Text aufmerksam."},{"id":"fragen","label":"Fragen","type":"questions","description":"Wählen Sie bei jeder Aufgabe A, B oder C."}],"variantCount":3,"officialStatus":"Not official telc/Zertify"}',1,25),
('pruefung-01-teil3','pruefung-01','teil3','Lesen – Teil 3','Welche Anzeige passt zu welcher Situation? Eine Anzeige passt nicht.','Lesen Sie die zehn Situationen und die zwölf Anzeigen. Ordnen Sie jeder Situation die passende Anzeige zu.','matching_ads','{"source":"original_practice_content","sourceSetId":"teil3-01","titleAr":"عروض مرتبطة بالحياة المستدامة","originalSetTitle":"Angebote rund um nachhaltiges Leben","slides":[{"id":"situationen","label":"Situationen","type":"situations","description":"Lesen Sie die zehn Situationen."},{"id":"anzeigen","label":"Anzeigen","type":"ads","description":"Wählen Sie für jede Situation die passende Anzeige."}],"variantCount":3,"officialStatus":"Not official telc/Zertify","ads":[{"code":"A","text":"Jeden zweiten Samstag helfen Fachleute und Freiwillige beim Reparieren von kleinen Elektrogeräten. Bitte bringen Sie das Gerät und, wenn möglich, eine Beschreibung des Problems mit. Materialkosten werden berechnet."},{"code":"B","text":"Unser Gemeinschaftsgarten nimmt neue Mitglieder auf. Wer regelmäßig mitarbeiten möchte, kann ein eigenes Beet pflegen oder bei der Bewässerung helfen. Treffen: Mittwoch ab 17 Uhr."},{"code":"C","text":"In diesem Abendkurs lernen Sie, Bremsen einzustellen, Reifen zu wechseln und eine Kette zu reinigen. Eigenes Fahrrad und Grundwerkzeug können mitgebracht werden."},{"code":"D","text":"Ein vierwöchiger Kurs zeigt, wie man mit regionalen Produkten, wenig Energie und kreativen Resterezepten kocht. Der Kurs ist für Anfänger geeignet."},{"code":"E","text":"Unser Schlaflabor untersucht Schlafstörungen und bietet individuelle Beratung nach ärztlicher Überweisung. Termine nach Vereinbarung."},{"code":"F","text":"Gut erhaltene Kinderkleidung, Kinderwagen und Spielzeug wechseln bei uns den Besitzer. Familien können Verkaufszeiten online reservieren und nicht verkaufte Ware wieder abholen."},{"code":"G","text":"Mit unserem Carsharing-Angebot stehen mehrere Fahrzeuge an festen Stationen bereit. Abgerechnet wird nach Zeit und gefahrenen Kilometern. Die Registrierung erfolgt über eine App."},{"code":"H","text":"Bei einem kostenlosen Spaziergang durch den Stadtpark erklärt eine Biologin, welche Vögel dort leben und wie man sie erkennt. Ferngläser können ausgeliehen werden."},{"code":"I","text":"Sie möchten regelmäßig Deutsch sprechen? Unser Tandemprogramm bringt Lernende mit deutschsprachigen Freiwilligen zusammen. Die Treffen finden in Cafés oder online statt."},{"code":"J","text":"Energieberater prüfen gemeinsam mit Ihnen Heizung, Fenster und Stromverbrauch. Sie erhalten konkrete Vorschläge, wie Sie Kosten und Energieverbrauch senken können."},{"code":"K","text":"Jeden Freitag kochen Menschen aus dem Viertel ein gemeinsames Abendessen. Die Zutaten werden nach Möglichkeit gerettet oder regional eingekauft. Neue Gäste sind willkommen."},{"code":"L","text":"In zwei Workshops üben Sie Anschreiben, Lebenslauf und Vorstellungsgespräch. Das Angebot richtet sich an Arbeitssuchende und findet vormittags statt."},{"code":"X","text":"Für diese Situation gibt es in den Anzeigen kein geeignetes Angebot."}]}',2,25);

INSERT OR IGNORE INTO reading_exam_sections (id,exam_id,section_code,title,instructions,main_text,exercise_type,extra_data_json,order_index,points_max) VALUES
('pruefung-01-sprach1','pruefung-01','sprach1','Sprachbausteine – Teil 1','Wählen Sie für jede Lücke die passende Lösung.','Liebe Nora,

vielen Dank (21) deine Nachricht. Ich habe mich sehr gefreut, (22) du dich nach meinem neuen Arbeitsweg erkundigt hast. Seit drei Monaten fahre ich mit dem Fahrrad zur Arbeit, (23) ich näher an die Innenstadt gezogen bin. Am Anfang war ich unsicher, (24) ich jeden Morgen fast acht Kilometer zurücklegen musste. Inzwischen bin ich (25) die Strecke gewöhnt und brauche sogar weniger Zeit (26) früher. Besonders angenehm ist, dass ich unterwegs einen Park durchquere, (27) ich eine kurze Pause mache. Wenn es regnet, nehme ich die Bahn, (28) Fahrkarte ich schon am Vorabend auf mein Handy lade. Dadurch muss ich morgens nicht (29) lange am Automaten warten. Ich kann dir nur empfehlen, es ebenfalls (30) versuchen.

Viele Grüße
Lea','gap_three_options','{"source":"original_practice_content","sourceSetId":"sprach1-01","titleAr":"الذهاب إلى العمل بالدراجة","originalSetTitle":"Mit dem Fahrrad zur Arbeit","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie den Text aufmerksam."},{"id":"luecken","label":"Lücken","type":"gaps","description":"Wählen Sie den passenden Ausdruck für jede Lücke."}],"variantCount":3,"officialStatus":"Not official telc/Zertify"}',3,15),
('pruefung-01-sprach2','pruefung-01','sprach2','Sprachbausteine – Teil 2','Setzen Sie die passenden Wörter aus der Wortliste ein. Einige Wörter bleiben übrig.','Immer mehr Städte unterstützen Projekte, (31) Lebensmittel retten und gleichzeitig Menschen zusammenbringen. Freiwillige holen Produkte in Geschäften ab, (32) sie entsorgt werden, und bringen sie zu Ausgabestellen. Die Initiative weist darauf hin, dass sich alle Beteiligten an (33) Regeln orientieren müssen. Wer sich (34) Projekt beteiligen möchte, muss sich vorher in einer App registrieren. Ein Teil der geretteten Waren wird (35) soziale Einrichtungen gebracht und dort (36) an Menschen verteilt, die Unterstützung brauchen. Durch die Abholung entsteht (37) weniger Müll; zugleich lernen die Beteiligten, (38) sie Lebensmittel bewusster planen. Fachleute betonen, (39) solche Projekte nur dann langfristig wirken, wenn sie mit Verbraucherbildung (40) werden.','gap_word_bank','{"source":"original_practice_content","sourceSetId":"sprach2-01","titleAr":"إنقاذ الطعام","originalSetTitle":"Lebensmittel retten","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie den Text aufmerksam."},{"id":"luecken","label":"Lücken","type":"gaps","description":"Wählen Sie den passenden Ausdruck für jede Lücke."}],"variantCount":3,"officialStatus":"Not official telc/Zertify","wordBank":[{"code":"A","text":"die"},{"code":"B","text":"bevor"},{"code":"C","text":"den"},{"code":"D","text":"am"},{"code":"E","text":"an"},{"code":"F","text":"kostenlos"},{"code":"G","text":"nicht"},{"code":"H","text":"wie"},{"code":"I","text":"dass"},{"code":"J","text":"verbunden"},{"code":"K","text":"obwohl"},{"code":"L","text":"dadurch"},{"code":"M","text":"während"},{"code":"N","text":"eines"},{"code":"O","text":"zu"}]}',4,15),
('pruefung-02-teil1','pruefung-02','teil1','Lesen – Teil 1','Ordnen Sie jedem Text die passende Überschrift zu. Zwei Überschriften bleiben übrig.','1. Eine Hochschule vermittelt Studierende über eine digitale Plattform an passende Lernpartner. Wer sich anmeldet, gibt an, für welches Fach er Unterstützung sucht und wann er Zeit hat. So entstehen kleine Lerngruppen, in denen die Teilnehmer gemeinsam üben und sich gegenseitig erklären, was sie verstanden haben.

2. Ein mittelständischer Betrieb hat einen Teil seiner Büros in einen offenen Arbeitsbereich umgebaut. Mitarbeitende aus verschiedenen Abteilungen teilen dort Besprechungsräume und technische Ausstattung. Nach Angaben der Geschäftsführung werden dadurch Räume besser genutzt, gleichzeitig entstehen häufiger spontane Gespräche über gemeinsame Projekte.

3. Digitale Notizprogramme können mehr als handschriftliche Stichpunkte speichern. Sie verbinden Termine, Dokumente und Suchbegriffe miteinander. Wer seine Notizen konsequent mit kurzen Schlagwörtern versieht, findet auch Monate später schnell die Information, die er für eine Aufgabe benötigt.

4. Viele neue Beschäftigte wissen fachlich viel, kennen aber die Abläufe eines Unternehmens noch nicht. Ein Mentoringprogramm stellt ihnen deshalb erfahrene Kolleginnen und Kollegen zur Seite. Diese geben keine fertigen Lösungen vor, sondern erklären typische Entscheidungen und helfen bei den ersten eigenen Projekten.

5. Ein Verlag testet ein Arbeitsmodell mit vier regulären Arbeitstagen. Die tägliche Arbeitszeit bleibt gleich, und die Teams planen ihre Aufgaben genauer. Nach sechs Monaten berichten viele Beschäftigte von mehr Erholung. Die Leitung betont jedoch, dass das Modell nur funktioniert, wenn Kundentermine und Vertretungen klar geregelt sind.','matching_titles','{"source":"original_practice_content","sourceSetId":"teil1-02","titleAr":"التعلم والعمل في تحوّل مستمر","originalSetTitle":"Lernen und Arbeiten im Wandel","slides":[{"id":"texte","label":"Texte","type":"texts","description":"Lesen Sie die fünf kurzen Mitteilungen."},{"id":"ueberschriften","label":"Überschriften","type":"headlines","description":"Ordnen Sie jeder Mitteilung die passende Überschrift zu."}],"variantCount":3,"officialStatus":"Not official telc/Zertify","titles":[{"code":"A","text":"Weniger Papier, bessere Übersicht"},{"code":"B","text":"Ein zusätzlicher freier Tag braucht klare Regeln"},{"code":"C","text":"Gemeinsam arbeiten, obwohl die Abteilungen verschieden sind"},{"code":"D","text":"Prüfungen werden vollständig abgeschafft"},{"code":"E","text":"Erholung durch eine neue Arbeitswoche"},{"code":"F","text":"Die Universität ersetzt alle Lehrkräfte durch Apps"},{"code":"G","text":"Gemeinsam lernen, individuell vorankommen"},{"code":"H","text":"Erfahrung wird an Berufsanfänger weitergegeben"},{"code":"I","text":"Nur Einzelbüros erhöhen die Leistung"},{"code":"J","text":"Mit Schlagwörtern Informationen wiederfinden"}]}',0,25);

INSERT OR IGNORE INTO reading_exam_sections (id,exam_id,section_code,title,instructions,main_text,exercise_type,extra_data_json,order_index,points_max) VALUES
('pruefung-02-teil2','pruefung-02','teil2','Lesen – Teil 2','Lesen Sie den Text und wählen Sie bei jeder Aufgabe die richtige Lösung.','Ein mittelständisches Unternehmen hat sechs Monate lang eine Vier-Tage-Woche getestet. Die Beschäftigten arbeiteten nicht weniger Stunden pro Woche, sondern verteilten ihre Arbeitszeit auf vier längere Tage. Ziel des Versuchs war es herauszufinden, ob sich die Organisation verbessern lässt, ohne dass Kunden schlechter erreichbar sind.

Damit der zusätzliche freie Tag nicht zu Problemen führte, planten die Teams ihre Aufgaben früher als bisher. Besprechungen durften nur noch stattfinden, wenn eine kurze Tagesordnung vorlag. Außerdem wechselten sich die Mitarbeiterinnen und Mitarbeiter im Kundendienst ab. So blieb die Telefonleitung von Montag bis Freitag besetzt, obwohl nicht alle Personen an jedem Tag arbeiteten.

Nach drei Monaten zeigte sich, dass einige Teams zunächst mehr Zeit für die Planung brauchten. Später wurden die Abläufe jedoch klarer. Die Zahl der kurzfristigen Krankmeldungen sank leicht, und die Produktivität blieb nach Angaben der Geschäftsleitung stabil. Einige Beschäftigte berichteten außerdem, dass sie den freien Tag für Behördengänge, Weiterbildung oder die Betreuung von Angehörigen nutzen konnten.

Die Ergebnisse lassen sich nicht automatisch auf jedes Unternehmen übertragen. In Bereichen mit täglichem Publikumsverkehr wären andere Schichtmodelle notwendig. Die Personalabteilung empfiehlt deshalb, vor einer Einführung genau zu prüfen, welche Aufgaben gemeinsam erledigt werden müssen und welche Vertretungen nötig sind. Die Vier-Tage-Woche wird im Unternehmen weitergeführt, aber zunächst nur in den Abteilungen, die an der Testphase teilgenommen haben.','multiple_choice','{"source":"original_practice_content","sourceSetId":"teil2-02","titleAr":"أربعة أيام عمل – مع الحفاظ على التواصل","originalSetTitle":"Vier Tage arbeiten – und trotzdem erreichbar?","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie den Text aufmerksam."},{"id":"fragen","label":"Fragen","type":"questions","description":"Wählen Sie bei jeder Aufgabe A, B oder C."}],"variantCount":3,"officialStatus":"Not official telc/Zertify"}',1,25),
('pruefung-02-teil3','pruefung-02','teil3','Lesen – Teil 3','Welche Anzeige passt zu welcher Situation? Eine Anzeige passt nicht.','Lesen Sie die zehn Situationen und die zwölf Anzeigen. Ordnen Sie jeder Situation die passende Anzeige zu.','matching_ads','{"source":"original_practice_content","sourceSetId":"teil3-02","titleAr":"عروض للتعليم والعمل الرقميين","originalSetTitle":"Angebote für digitale Bildung und Arbeit","slides":[{"id":"situationen","label":"Situationen","type":"situations","description":"Lesen Sie die zehn Situationen."},{"id":"anzeigen","label":"Anzeigen","type":"ads","description":"Wählen Sie für jede Situation die passende Anzeige."}],"variantCount":3,"officialStatus":"Not official telc/Zertify","ads":[{"code":"A","text":"Der Abendkurs richtet sich an Beschäftigte, die Tabellen übersichtlich gestalten, Formeln nutzen und einfache Auswertungen erstellen möchten. Vorkenntnisse sind nicht erforderlich."},{"code":"B","text":"In drei Terminen lernen Sie, Nachrichtenquellen zu prüfen, manipulierte Bilder zu erkennen und Ihre persönlichen Daten in sozialen Netzwerken besser zu schützen."},{"code":"C","text":"Junge Beschäftigte treffen sich monatlich mit erfahrenen Fachkräften aus ihrer Branche. Im Mittelpunkt stehen berufliche Entscheidungen, Kommunikation und der Aufbau eines Netzwerks."},{"code":"D","text":"Flexible Arbeitsplätze, Besprechungsräume und schnelles Internet – tageweise oder monatlich buchbar. Ideal für Selbstständige und Beschäftigte, die nicht jeden Tag im Homeoffice arbeiten möchten."},{"code":"E","text":"Physiotherapeutinnen zeigen Übungen für Nacken, Schultern und Rücken. Der Kurs richtet sich an Personen, die lange am Schreibtisch sitzen."},{"code":"F","text":"Dieser Workshop hilft Teams, Aufgaben zu priorisieren, realistische Fristen zu vereinbaren und Besprechungen effizienter zu gestalten."},{"code":"G","text":"Unser kleines Studio kann für Audioaufnahmen, Interviews und Sprachprojekte gebucht werden. Mikrofone und Schnittprogramm sind vorhanden."},{"code":"H","text":"Lernende aus verschiedenen Ländern treffen sich per Video, um Deutsch zu sprechen. Die Plattform ordnet Gesprächspartner nach Niveau und Interessen zu."},{"code":"I","text":"Sie üben Lebenslauf, Anschreiben und Vorstellungsgespräch mit einer Karriereberaterin. Eigene Bewerbungsunterlagen können mitgebracht werden."},{"code":"J","text":"In den Ferien entwickeln Jugendliche ein kleines Computerspiel und lernen dabei die Grundlagen einer Programmiersprache."},{"code":"K","text":"Kunstinteressierte können an einer geführten Online-Tour durch europäische Museen teilnehmen. Die Veranstaltung ist kostenlos, Fragen werden im Chat beantwortet."},{"code":"L","text":"Personalverantwortliche berichten über die Einführung einer Vier-Tage-Woche, notwendige Vertretungsregeln und die Auswertung von Pilotprojekten."},{"code":"X","text":"Für diese Situation gibt es in den Anzeigen kein geeignetes Angebot."}]}',2,25),
('pruefung-02-sprach1','pruefung-02','sprach1','Sprachbausteine – Teil 1','Wählen Sie für jede Lücke die passende Lösung.','Liebe Samira,

ich wollte dir erzählen, wie mein erster Onlinekurs gelaufen ist. Obwohl ich zunächst Angst (21) technischen Problemen hatte, funktionierte alles problemlos. Die Dozentin erklärte am Anfang, (22) wir die Lernplattform benutzen sollten, und bat uns, (23) Mikrofone auszuschalten, wenn wir nicht sprechen. Nachdem wir die erste Aufgabe beendet (24), konnten wir Fragen im Chat stellen. Ich fand besonders hilfreich, dass man die Unterrichtsmaterialien jederzeit (25) konnte. Die Teilnahme hat mich motiviert, mich (26) einem weiterführenden Kurs anzumelden. Falls du Interesse (27) hast, schicke ich dir den Link, (28) du dich registrieren kannst. Der Kurs findet immer montags (29) 18 Uhr statt. Vielleicht besuchen wir bald gemeinsam einen Kurs (30) neuen Thema.

Herzliche Grüße
Mina','gap_three_options','{"source":"original_practice_content","sourceSetId":"sprach1-02","titleAr":"دورة عبر الإنترنت ونتائجها","originalSetTitle":"Ein Onlinekurs mit Folgen","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie den Text aufmerksam."},{"id":"luecken","label":"Lücken","type":"gaps","description":"Wählen Sie den passenden Ausdruck für jede Lücke."}],"variantCount":3,"officialStatus":"Not official telc/Zertify"}',3,15);

INSERT OR IGNORE INTO reading_exam_sections (id,exam_id,section_code,title,instructions,main_text,exercise_type,extra_data_json,order_index,points_max) VALUES
('pruefung-02-sprach2','pruefung-02','sprach2','Sprachbausteine – Teil 2','Setzen Sie die passenden Wörter aus der Wortliste ein. Einige Wörter bleiben übrig.','Immer mehr Firmen testen Arbeitsmodelle, bei denen Angestellte einen Teil ihrer Aufgaben von zu Hause (31) erledigen. Entscheidend ist, dass die Teams regelmäßig (32) Kontakt bleiben. Eine Videokonferenz ersetzt jedoch nicht automatisch jedes persönliche Gespräch, (33) manche Fragen lassen sich im direkten Austausch schneller klären. Deshalb empfehlen Fachleute, dass man vor jedem digitalen Treffen prüft, (34) wirklich alle Teilnehmenden nötig sind. Wer häufig am Bildschirm arbeitet, sollte außerdem darauf achten, regelmäßig (35) zu machen, damit die Konzentration nicht (36). Unternehmen, (37) klare Regeln für Erreichbarkeit und Pausen schaffen, berichten oft, dass (38) Mitarbeitenden zufriedener sind. Voraussetzung (39) ist allerdings, dass die Aufgaben klar verteilt werden und Führungskräfte (40) Vertrauen entgegenbringen.','gap_word_bank','{"source":"original_practice_content","sourceSetId":"sprach2-02","titleAr":"نماذج عمل مدعومة رقمياً","originalSetTitle":"Arbeitsmodelle mit digitaler Unterstützung","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie den Text aufmerksam."},{"id":"luecken","label":"Lücken","type":"gaps","description":"Wählen Sie den passenden Ausdruck für jede Lücke."}],"variantCount":3,"officialStatus":"Not official telc/Zertify","wordBank":[{"code":"A","text":"aus"},{"code":"B","text":"in"},{"code":"C","text":"weil"},{"code":"D","text":"ob"},{"code":"E","text":"Pausen"},{"code":"F","text":"nachlässt"},{"code":"G","text":"die"},{"code":"H","text":"ihre"},{"code":"I","text":"dafür"},{"code":"J","text":"ihnen"},{"code":"K","text":"obwohl"},{"code":"L","text":"daran"},{"code":"M","text":"während"},{"code":"N","text":"seinen"},{"code":"O","text":"zu"}]}',4,15),
('teil1-01-teil1','teil1-01','teil1','Kleine Veränderungen, große Wirkung','Ordnen Sie jedem Text die passende Überschrift zu. Zwei Überschriften bleiben übrig.','1. Die Stadtverwaltung verwandelt mehrere graue Bushaltestellen in kleine Klimainseln. Neue Dächer werden mit Pflanzen begrünt, speichern einen Teil des Regenwassers und spenden im Sommer Schatten. Außerdem sollen die bepflanzten Haltestellen die Luftqualität im dicht bebauten Zentrum verbessern.

2. Viele Beschäftigte versuchen, ohne Unterbrechung durchzuarbeiten. Ein Forschungsprojekt zeigt jedoch, dass kurze Bewegungspausen die Aufmerksamkeit steigern können. Schon neunzig Sekunden Aufstehen, Dehnen oder Blickwechsel reichen aus, damit sich die Konzentration nach einer längeren Arbeitsphase wieder erholt.

3. In immer mehr Stadtteilen teilen Nachbarinnen und Nachbarn Lebensmittel, die in Geschäften nicht mehr verkauft werden dürfen, obwohl sie noch genießbar sind. Die beteiligten Läden sparen Entsorgungskosten, während die Abholenden gemeinsam entscheiden, wie die Waren verteilt werden.

4. In einem Reparaturcafé bringen Bürgerinnen und Bürger kaputte Lampen, Toaster oder Radios mit. Ehrenamtliche helfen bei der Fehlersuche und zeigen, wie man einfache Reparaturen selbst durchführen kann. Bezahlt wird nur das Material; wichtiger ist der Austausch von Wissen.

5. Wer ein großes Fahrrad für Einkäufe oder den Transport von Kindern benötigt, muss es nicht unbedingt kaufen. Die Stadtbibliothek verleiht neben Büchern inzwischen auch Lastenräder. Nach einer kurzen Einweisung können registrierte Nutzerinnen und Nutzer die Räder für mehrere Tage reservieren.','matching_titles','{"source":"original_practice_content","sourceSetId":"teil1-01","titleAr":"تغييرات صغيرة، تأثير كبير","originalSetTitle":"Kleine Veränderungen, große Wirkung","slides":[{"id":"texte","label":"Texte","type":"texts","description":"Lesen Sie die fünf kurzen Mitteilungen."},{"id":"ueberschriften","label":"Überschriften","type":"headlines","description":"Ordnen Sie jeder Mitteilung die passende Überschrift zu."}],"variantCount":3,"officialStatus":"Not official telc/Zertify","titles":[{"code":"A","text":"Lebensmittel teilen statt wegwerfen"},{"code":"B","text":"Mini-Pausen stärken die Konzentration"},{"code":"C","text":"Alte Geräte erhalten eine zweite Chance"},{"code":"D","text":"Neue Klimainseln entstehen an Haltestellen"},{"code":"E","text":"Fahrradfahren ist nur etwas für Sportler"},{"code":"F","text":"Lastenräder kann man auch ausleihen"},{"code":"G","text":"Ein Garten für alle Generationen"},{"code":"H","text":"Schnelle Lösungen für hohe Stromkosten"},{"code":"I","text":"Mehr Urlaub durch bessere Planung"},{"code":"J","text":"Wie Kinder sicher schwimmen lernen"}]}',0,25),
('teil1-02-teil1','teil1-02','teil1','Lernen und Arbeiten im Wandel','Ordnen Sie jedem Text die passende Überschrift zu. Zwei Überschriften bleiben übrig.','1. Eine Hochschule vermittelt Studierende über eine digitale Plattform an passende Lernpartner. Wer sich anmeldet, gibt an, für welches Fach er Unterstützung sucht und wann er Zeit hat. So entstehen kleine Lerngruppen, in denen die Teilnehmer gemeinsam üben und sich gegenseitig erklären, was sie verstanden haben.

2. Ein mittelständischer Betrieb hat einen Teil seiner Büros in einen offenen Arbeitsbereich umgebaut. Mitarbeitende aus verschiedenen Abteilungen teilen dort Besprechungsräume und technische Ausstattung. Nach Angaben der Geschäftsführung werden dadurch Räume besser genutzt, gleichzeitig entstehen häufiger spontane Gespräche über gemeinsame Projekte.

3. Digitale Notizprogramme können mehr als handschriftliche Stichpunkte speichern. Sie verbinden Termine, Dokumente und Suchbegriffe miteinander. Wer seine Notizen konsequent mit kurzen Schlagwörtern versieht, findet auch Monate später schnell die Information, die er für eine Aufgabe benötigt.

4. Viele neue Beschäftigte wissen fachlich viel, kennen aber die Abläufe eines Unternehmens noch nicht. Ein Mentoringprogramm stellt ihnen deshalb erfahrene Kolleginnen und Kollegen zur Seite. Diese geben keine fertigen Lösungen vor, sondern erklären typische Entscheidungen und helfen bei den ersten eigenen Projekten.

5. Ein Verlag testet ein Arbeitsmodell mit vier regulären Arbeitstagen. Die tägliche Arbeitszeit bleibt gleich, und die Teams planen ihre Aufgaben genauer. Nach sechs Monaten berichten viele Beschäftigte von mehr Erholung. Die Leitung betont jedoch, dass das Modell nur funktioniert, wenn Kundentermine und Vertretungen klar geregelt sind.','matching_titles','{"source":"original_practice_content","sourceSetId":"teil1-02","titleAr":"التعلم والعمل في تحوّل مستمر","originalSetTitle":"Lernen und Arbeiten im Wandel","slides":[{"id":"texte","label":"Texte","type":"texts","description":"Lesen Sie die fünf kurzen Mitteilungen."},{"id":"ueberschriften","label":"Überschriften","type":"headlines","description":"Ordnen Sie jeder Mitteilung die passende Überschrift zu."}],"variantCount":3,"officialStatus":"Not official telc/Zertify","titles":[{"code":"A","text":"Weniger Papier, bessere Übersicht"},{"code":"B","text":"Ein zusätzlicher freier Tag braucht klare Regeln"},{"code":"C","text":"Gemeinsam arbeiten, obwohl die Abteilungen verschieden sind"},{"code":"D","text":"Prüfungen werden vollständig abgeschafft"},{"code":"E","text":"Erholung durch eine neue Arbeitswoche"},{"code":"F","text":"Die Universität ersetzt alle Lehrkräfte durch Apps"},{"code":"G","text":"Gemeinsam lernen, individuell vorankommen"},{"code":"H","text":"Erfahrung wird an Berufsanfänger weitergegeben"},{"code":"I","text":"Nur Einzelbüros erhöhen die Leistung"},{"code":"J","text":"Mit Schlagwörtern Informationen wiederfinden"}]}',0,25);

INSERT OR IGNORE INTO reading_exam_sections (id,exam_id,section_code,title,instructions,main_text,exercise_type,extra_data_json,order_index,points_max) VALUES
('teil2-01-teil2','teil2-01','teil2','Ein Garten, der die Nachbarschaft kühlt','Lesen Sie den Text und wählen Sie bei jeder Aufgabe die richtige Lösung.','Auf einem früheren Parkplatz am Rand einer dicht bebauten Wohnsiedlung wächst heute ein gemeinschaftlicher Garten. Die Idee entstand während eines besonders heißen Sommers. Anwohnerinnen und Anwohner suchten einen Ort, an dem sie sich treffen konnten, ohne in einer aufgeheizten Wohnung oder auf einer betonierten Fläche zu sitzen. Die Stadt stellte das Grundstück zunächst für fünf Jahre zur Verfügung.

Die Beteiligten legten Beete an, pflanzten Bäume und bauten eine große Zisterne. Das Regenwasser von den umliegenden Dächern wird gesammelt und in trockenen Wochen zum Gießen verwendet. Für die Planung engagierten sich nicht nur Gartenexperten. Auch Kinder, ältere Menschen und Familien, die bisher kaum Kontakt miteinander hatten, übernahmen eigene Aufgaben.

Im ersten Jahr mussten die Organisatoren lernen, dass ein Garten nicht automatisch von allein funktioniert. Einige Pflanzen wurden zu dicht gesetzt, andere vertrugen die starke Sonne nicht. Außerdem fehlte anfangs ein verbindlicher Plan für das Gießen. Nach einer gemeinsamen Auswertung teilten die Gruppen die Beete neu auf und führten einen einfachen Kalender ein.

Heute ist der Garten nicht nur ein Ort für Gemüse. Im Sommer finden dort kostenlose Kochabende statt, bei denen die Ernte verarbeitet wird. Für die kommenden Jahre wünschen sich die Initiatoren ein begrüntes Dach über dem Treffpunkt und weitere Zisternen. Sie hoffen, dass das Projekt auch andere Stadtteile dazu anregt, ungenutzte Flächen gemeinsam zu verändern.','multiple_choice','{"source":"original_practice_content","sourceSetId":"teil2-01","titleAr":"حديقة تُنعش الحي","originalSetTitle":"Ein Garten, der die Nachbarschaft kühlt","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie den Text aufmerksam."},{"id":"fragen","label":"Fragen","type":"questions","description":"Wählen Sie bei jeder Aufgabe A, B oder C."}],"variantCount":3,"officialStatus":"Not official telc/Zertify"}',0,25),
('teil2-02-teil2','teil2-02','teil2','Vier Tage arbeiten – und trotzdem erreichbar?','Lesen Sie den Text und wählen Sie bei jeder Aufgabe die richtige Lösung.','Ein mittelständisches Unternehmen hat sechs Monate lang eine Vier-Tage-Woche getestet. Die Beschäftigten arbeiteten nicht weniger Stunden pro Woche, sondern verteilten ihre Arbeitszeit auf vier längere Tage. Ziel des Versuchs war es herauszufinden, ob sich die Organisation verbessern lässt, ohne dass Kunden schlechter erreichbar sind.

Damit der zusätzliche freie Tag nicht zu Problemen führte, planten die Teams ihre Aufgaben früher als bisher. Besprechungen durften nur noch stattfinden, wenn eine kurze Tagesordnung vorlag. Außerdem wechselten sich die Mitarbeiterinnen und Mitarbeiter im Kundendienst ab. So blieb die Telefonleitung von Montag bis Freitag besetzt, obwohl nicht alle Personen an jedem Tag arbeiteten.

Nach drei Monaten zeigte sich, dass einige Teams zunächst mehr Zeit für die Planung brauchten. Später wurden die Abläufe jedoch klarer. Die Zahl der kurzfristigen Krankmeldungen sank leicht, und die Produktivität blieb nach Angaben der Geschäftsleitung stabil. Einige Beschäftigte berichteten außerdem, dass sie den freien Tag für Behördengänge, Weiterbildung oder die Betreuung von Angehörigen nutzen konnten.

Die Ergebnisse lassen sich nicht automatisch auf jedes Unternehmen übertragen. In Bereichen mit täglichem Publikumsverkehr wären andere Schichtmodelle notwendig. Die Personalabteilung empfiehlt deshalb, vor einer Einführung genau zu prüfen, welche Aufgaben gemeinsam erledigt werden müssen und welche Vertretungen nötig sind. Die Vier-Tage-Woche wird im Unternehmen weitergeführt, aber zunächst nur in den Abteilungen, die an der Testphase teilgenommen haben.','multiple_choice','{"source":"original_practice_content","sourceSetId":"teil2-02","titleAr":"أربعة أيام عمل – مع الحفاظ على التواصل","originalSetTitle":"Vier Tage arbeiten – und trotzdem erreichbar?","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie den Text aufmerksam."},{"id":"fragen","label":"Fragen","type":"questions","description":"Wählen Sie bei jeder Aufgabe A, B oder C."}],"variantCount":3,"officialStatus":"Not official telc/Zertify"}',0,25),
('teil3-01-teil3','teil3-01','teil3','Angebote rund um nachhaltiges Leben','Welche Anzeige passt zu welcher Situation? Eine Anzeige passt nicht.','Lesen Sie die zehn Situationen und die zwölf Anzeigen. Ordnen Sie jeder Situation die passende Anzeige zu.','matching_ads','{"source":"original_practice_content","sourceSetId":"teil3-01","titleAr":"عروض مرتبطة بالحياة المستدامة","originalSetTitle":"Angebote rund um nachhaltiges Leben","slides":[{"id":"situationen","label":"Situationen","type":"situations","description":"Lesen Sie die zehn Situationen."},{"id":"anzeigen","label":"Anzeigen","type":"ads","description":"Wählen Sie für jede Situation die passende Anzeige."}],"variantCount":3,"officialStatus":"Not official telc/Zertify","ads":[{"code":"A","text":"Jeden zweiten Samstag helfen Fachleute und Freiwillige beim Reparieren von kleinen Elektrogeräten. Bitte bringen Sie das Gerät und, wenn möglich, eine Beschreibung des Problems mit. Materialkosten werden berechnet."},{"code":"B","text":"Unser Gemeinschaftsgarten nimmt neue Mitglieder auf. Wer regelmäßig mitarbeiten möchte, kann ein eigenes Beet pflegen oder bei der Bewässerung helfen. Treffen: Mittwoch ab 17 Uhr."},{"code":"C","text":"In diesem Abendkurs lernen Sie, Bremsen einzustellen, Reifen zu wechseln und eine Kette zu reinigen. Eigenes Fahrrad und Grundwerkzeug können mitgebracht werden."},{"code":"D","text":"Ein vierwöchiger Kurs zeigt, wie man mit regionalen Produkten, wenig Energie und kreativen Resterezepten kocht. Der Kurs ist für Anfänger geeignet."},{"code":"E","text":"Unser Schlaflabor untersucht Schlafstörungen und bietet individuelle Beratung nach ärztlicher Überweisung. Termine nach Vereinbarung."},{"code":"F","text":"Gut erhaltene Kinderkleidung, Kinderwagen und Spielzeug wechseln bei uns den Besitzer. Familien können Verkaufszeiten online reservieren und nicht verkaufte Ware wieder abholen."},{"code":"G","text":"Mit unserem Carsharing-Angebot stehen mehrere Fahrzeuge an festen Stationen bereit. Abgerechnet wird nach Zeit und gefahrenen Kilometern. Die Registrierung erfolgt über eine App."},{"code":"H","text":"Bei einem kostenlosen Spaziergang durch den Stadtpark erklärt eine Biologin, welche Vögel dort leben und wie man sie erkennt. Ferngläser können ausgeliehen werden."},{"code":"I","text":"Sie möchten regelmäßig Deutsch sprechen? Unser Tandemprogramm bringt Lernende mit deutschsprachigen Freiwilligen zusammen. Die Treffen finden in Cafés oder online statt."},{"code":"J","text":"Energieberater prüfen gemeinsam mit Ihnen Heizung, Fenster und Stromverbrauch. Sie erhalten konkrete Vorschläge, wie Sie Kosten und Energieverbrauch senken können."},{"code":"K","text":"Jeden Freitag kochen Menschen aus dem Viertel ein gemeinsames Abendessen. Die Zutaten werden nach Möglichkeit gerettet oder regional eingekauft. Neue Gäste sind willkommen."},{"code":"L","text":"In zwei Workshops üben Sie Anschreiben, Lebenslauf und Vorstellungsgespräch. Das Angebot richtet sich an Arbeitssuchende und findet vormittags statt."},{"code":"X","text":"Für diese Situation gibt es in den Anzeigen kein geeignetes Angebot."}]}',0,25);

INSERT OR IGNORE INTO reading_exam_sections (id,exam_id,section_code,title,instructions,main_text,exercise_type,extra_data_json,order_index,points_max) VALUES
('teil3-02-teil3','teil3-02','teil3','Angebote für digitale Bildung und Arbeit','Welche Anzeige passt zu welcher Situation? Eine Anzeige passt nicht.','Lesen Sie die zehn Situationen und die zwölf Anzeigen. Ordnen Sie jeder Situation die passende Anzeige zu.','matching_ads','{"source":"original_practice_content","sourceSetId":"teil3-02","titleAr":"عروض للتعليم والعمل الرقميين","originalSetTitle":"Angebote für digitale Bildung und Arbeit","slides":[{"id":"situationen","label":"Situationen","type":"situations","description":"Lesen Sie die zehn Situationen."},{"id":"anzeigen","label":"Anzeigen","type":"ads","description":"Wählen Sie für jede Situation die passende Anzeige."}],"variantCount":3,"officialStatus":"Not official telc/Zertify","ads":[{"code":"A","text":"Der Abendkurs richtet sich an Beschäftigte, die Tabellen übersichtlich gestalten, Formeln nutzen und einfache Auswertungen erstellen möchten. Vorkenntnisse sind nicht erforderlich."},{"code":"B","text":"In drei Terminen lernen Sie, Nachrichtenquellen zu prüfen, manipulierte Bilder zu erkennen und Ihre persönlichen Daten in sozialen Netzwerken besser zu schützen."},{"code":"C","text":"Junge Beschäftigte treffen sich monatlich mit erfahrenen Fachkräften aus ihrer Branche. Im Mittelpunkt stehen berufliche Entscheidungen, Kommunikation und der Aufbau eines Netzwerks."},{"code":"D","text":"Flexible Arbeitsplätze, Besprechungsräume und schnelles Internet – tageweise oder monatlich buchbar. Ideal für Selbstständige und Beschäftigte, die nicht jeden Tag im Homeoffice arbeiten möchten."},{"code":"E","text":"Physiotherapeutinnen zeigen Übungen für Nacken, Schultern und Rücken. Der Kurs richtet sich an Personen, die lange am Schreibtisch sitzen."},{"code":"F","text":"Dieser Workshop hilft Teams, Aufgaben zu priorisieren, realistische Fristen zu vereinbaren und Besprechungen effizienter zu gestalten."},{"code":"G","text":"Unser kleines Studio kann für Audioaufnahmen, Interviews und Sprachprojekte gebucht werden. Mikrofone und Schnittprogramm sind vorhanden."},{"code":"H","text":"Lernende aus verschiedenen Ländern treffen sich per Video, um Deutsch zu sprechen. Die Plattform ordnet Gesprächspartner nach Niveau und Interessen zu."},{"code":"I","text":"Sie üben Lebenslauf, Anschreiben und Vorstellungsgespräch mit einer Karriereberaterin. Eigene Bewerbungsunterlagen können mitgebracht werden."},{"code":"J","text":"In den Ferien entwickeln Jugendliche ein kleines Computerspiel und lernen dabei die Grundlagen einer Programmiersprache."},{"code":"K","text":"Kunstinteressierte können an einer geführten Online-Tour durch europäische Museen teilnehmen. Die Veranstaltung ist kostenlos, Fragen werden im Chat beantwortet."},{"code":"L","text":"Personalverantwortliche berichten über die Einführung einer Vier-Tage-Woche, notwendige Vertretungsregeln und die Auswertung von Pilotprojekten."},{"code":"X","text":"Für diese Situation gibt es in den Anzeigen kein geeignetes Angebot."}]}',0,25),
('sprach1-01-sprach1','sprach1-01','sprach1','Mit dem Fahrrad zur Arbeit','Wählen Sie für jede Lücke die passende Lösung.','Liebe Nora,

vielen Dank (21) deine Nachricht. Ich habe mich sehr gefreut, (22) du dich nach meinem neuen Arbeitsweg erkundigt hast. Seit drei Monaten fahre ich mit dem Fahrrad zur Arbeit, (23) ich näher an die Innenstadt gezogen bin. Am Anfang war ich unsicher, (24) ich jeden Morgen fast acht Kilometer zurücklegen musste. Inzwischen bin ich (25) die Strecke gewöhnt und brauche sogar weniger Zeit (26) früher. Besonders angenehm ist, dass ich unterwegs einen Park durchquere, (27) ich eine kurze Pause mache. Wenn es regnet, nehme ich die Bahn, (28) Fahrkarte ich schon am Vorabend auf mein Handy lade. Dadurch muss ich morgens nicht (29) lange am Automaten warten. Ich kann dir nur empfehlen, es ebenfalls (30) versuchen.

Viele Grüße
Lea','gap_three_options','{"source":"original_practice_content","sourceSetId":"sprach1-01","titleAr":"الذهاب إلى العمل بالدراجة","originalSetTitle":"Mit dem Fahrrad zur Arbeit","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie den Text aufmerksam."},{"id":"luecken","label":"Lücken","type":"gaps","description":"Wählen Sie den passenden Ausdruck für jede Lücke."}],"variantCount":3,"officialStatus":"Not official telc/Zertify"}',0,15),
('sprach1-02-sprach1','sprach1-02','sprach1','Ein Onlinekurs mit Folgen','Wählen Sie für jede Lücke die passende Lösung.','Liebe Samira,

ich wollte dir erzählen, wie mein erster Onlinekurs gelaufen ist. Obwohl ich zunächst Angst (21) technischen Problemen hatte, funktionierte alles problemlos. Die Dozentin erklärte am Anfang, (22) wir die Lernplattform benutzen sollten, und bat uns, (23) Mikrofone auszuschalten, wenn wir nicht sprechen. Nachdem wir die erste Aufgabe beendet (24), konnten wir Fragen im Chat stellen. Ich fand besonders hilfreich, dass man die Unterrichtsmaterialien jederzeit (25) konnte. Die Teilnahme hat mich motiviert, mich (26) einem weiterführenden Kurs anzumelden. Falls du Interesse (27) hast, schicke ich dir den Link, (28) du dich registrieren kannst. Der Kurs findet immer montags (29) 18 Uhr statt. Vielleicht besuchen wir bald gemeinsam einen Kurs (30) neuen Thema.

Herzliche Grüße
Mina','gap_three_options','{"source":"original_practice_content","sourceSetId":"sprach1-02","titleAr":"دورة عبر الإنترنت ونتائجها","originalSetTitle":"Ein Onlinekurs mit Folgen","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie den Text aufmerksam."},{"id":"luecken","label":"Lücken","type":"gaps","description":"Wählen Sie den passenden Ausdruck für jede Lücke."}],"variantCount":3,"officialStatus":"Not official telc/Zertify"}',0,15);

INSERT OR IGNORE INTO reading_exam_sections (id,exam_id,section_code,title,instructions,main_text,exercise_type,extra_data_json,order_index,points_max) VALUES
('sprach2-01-sprach2','sprach2-01','sprach2','Lebensmittel retten','Setzen Sie die passenden Wörter aus der Wortliste ein. Einige Wörter bleiben übrig.','Immer mehr Städte unterstützen Projekte, (31) Lebensmittel retten und gleichzeitig Menschen zusammenbringen. Freiwillige holen Produkte in Geschäften ab, (32) sie entsorgt werden, und bringen sie zu Ausgabestellen. Die Initiative weist darauf hin, dass sich alle Beteiligten an (33) Regeln orientieren müssen. Wer sich (34) Projekt beteiligen möchte, muss sich vorher in einer App registrieren. Ein Teil der geretteten Waren wird (35) soziale Einrichtungen gebracht und dort (36) an Menschen verteilt, die Unterstützung brauchen. Durch die Abholung entsteht (37) weniger Müll; zugleich lernen die Beteiligten, (38) sie Lebensmittel bewusster planen. Fachleute betonen, (39) solche Projekte nur dann langfristig wirken, wenn sie mit Verbraucherbildung (40) werden.','gap_word_bank','{"source":"original_practice_content","sourceSetId":"sprach2-01","titleAr":"إنقاذ الطعام","originalSetTitle":"Lebensmittel retten","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie den Text aufmerksam."},{"id":"luecken","label":"Lücken","type":"gaps","description":"Wählen Sie den passenden Ausdruck für jede Lücke."}],"variantCount":3,"officialStatus":"Not official telc/Zertify","wordBank":[{"code":"A","text":"die"},{"code":"B","text":"bevor"},{"code":"C","text":"den"},{"code":"D","text":"am"},{"code":"E","text":"an"},{"code":"F","text":"kostenlos"},{"code":"G","text":"nicht"},{"code":"H","text":"wie"},{"code":"I","text":"dass"},{"code":"J","text":"verbunden"},{"code":"K","text":"obwohl"},{"code":"L","text":"dadurch"},{"code":"M","text":"während"},{"code":"N","text":"eines"},{"code":"O","text":"zu"}]}',0,15),
('sprach2-02-sprach2','sprach2-02','sprach2','Arbeitsmodelle mit digitaler Unterstützung','Setzen Sie die passenden Wörter aus der Wortliste ein. Einige Wörter bleiben übrig.','Immer mehr Firmen testen Arbeitsmodelle, bei denen Angestellte einen Teil ihrer Aufgaben von zu Hause (31) erledigen. Entscheidend ist, dass die Teams regelmäßig (32) Kontakt bleiben. Eine Videokonferenz ersetzt jedoch nicht automatisch jedes persönliche Gespräch, (33) manche Fragen lassen sich im direkten Austausch schneller klären. Deshalb empfehlen Fachleute, dass man vor jedem digitalen Treffen prüft, (34) wirklich alle Teilnehmenden nötig sind. Wer häufig am Bildschirm arbeitet, sollte außerdem darauf achten, regelmäßig (35) zu machen, damit die Konzentration nicht (36). Unternehmen, (37) klare Regeln für Erreichbarkeit und Pausen schaffen, berichten oft, dass (38) Mitarbeitenden zufriedener sind. Voraussetzung (39) ist allerdings, dass die Aufgaben klar verteilt werden und Führungskräfte (40) Vertrauen entgegenbringen.','gap_word_bank','{"source":"original_practice_content","sourceSetId":"sprach2-02","titleAr":"نماذج عمل مدعومة رقمياً","originalSetTitle":"Arbeitsmodelle mit digitaler Unterstützung","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie den Text aufmerksam."},{"id":"luecken","label":"Lücken","type":"gaps","description":"Wählen Sie den passenden Ausdruck für jede Lücke."}],"variantCount":3,"officialStatus":"Not official telc/Zertify","wordBank":[{"code":"A","text":"aus"},{"code":"B","text":"in"},{"code":"C","text":"weil"},{"code":"D","text":"ob"},{"code":"E","text":"Pausen"},{"code":"F","text":"nachlässt"},{"code":"G","text":"die"},{"code":"H","text":"ihre"},{"code":"I","text":"dafür"},{"code":"J","text":"ihnen"},{"code":"K","text":"obwohl"},{"code":"L","text":"daran"},{"code":"M","text":"während"},{"code":"N","text":"seinen"},{"code":"O","text":"zu"}]}',0,15);

