('pruefung-01-teil2-q-5-C','pruefung-01-teil2-q-5','C','Sie möchten den Treffpunkt begrünen und weitere Zisternen bauen.',0,NULL,2),
('pruefung-01-teil3-q-1-A','pruefung-01-teil3-q-1','A','Jeden zweiten Samstag helfen Fachleute und Freiwillige beim Reparieren von kleinen Elektrogeräten. Bitte bringen Sie das Gerät und, wenn möglich, eine Beschreibung des Problems mit. Materialkosten werden berechnet.',0,NULL,0),
('pruefung-01-teil3-q-1-B','pruefung-01-teil3-q-1','B','Unser Gemeinschaftsgarten nimmt neue Mitglieder auf. Wer regelmäßig mitarbeiten möchte, kann ein eigenes Beet pflegen oder bei der Bewässerung helfen. Treffen: Mittwoch ab 17 Uhr.',0,NULL,1),
('pruefung-01-teil3-q-1-C','pruefung-01-teil3-q-1','C','In diesem Abendkurs lernen Sie, Bremsen einzustellen, Reifen zu wechseln und eine Kette zu reinigen. Eigenes Fahrrad und Grundwerkzeug können mitgebracht werden.',1,'Passende Anzeige.',2),
('pruefung-01-teil3-q-1-D','pruefung-01-teil3-q-1','D','Ein vierwöchiger Kurs zeigt, wie man mit regionalen Produkten, wenig Energie und kreativen Resterezepten kocht. Der Kurs ist für Anfänger geeignet.',0,NULL,3),
('pruefung-01-teil3-q-1-E','pruefung-01-teil3-q-1','E','Unser Schlaflabor untersucht Schlafstörungen und bietet individuelle Beratung nach ärztlicher Überweisung. Termine nach Vereinbarung.',0,NULL,4);

INSERT OR IGNORE INTO reading_options (id,question_id,code,text,is_correct,explanation,order_index) VALUES
('pruefung-01-teil3-q-1-F','pruefung-01-teil3-q-1','F','Gut erhaltene Kinderkleidung, Kinderwagen und Spielzeug wechseln bei uns den Besitzer. Familien können Verkaufszeiten online reservieren und nicht verkaufte Ware wieder abholen.',0,NULL,5),
('pruefung-01-teil3-q-1-G','pruefung-01-teil3-q-1','G','Mit unserem Carsharing-Angebot stehen mehrere Fahrzeuge an festen Stationen bereit. Abgerechnet wird nach Zeit und gefahrenen Kilometern. Die Registrierung erfolgt über eine App.',0,NULL,6),
('pruefung-01-teil3-q-1-H','pruefung-01-teil3-q-1','H','Bei einem kostenlosen Spaziergang durch den Stadtpark erklärt eine Biologin, welche Vögel dort leben und wie man sie erkennt. Ferngläser können ausgeliehen werden.',0,NULL,7),
('pruefung-01-teil3-q-1-I','pruefung-01-teil3-q-1','I','Sie möchten regelmäßig Deutsch sprechen? Unser Tandemprogramm bringt Lernende mit deutschsprachigen Freiwilligen zusammen. Die Treffen finden in Cafés oder online statt.',0,NULL,8),
('pruefung-01-teil3-q-1-J','pruefung-01-teil3-q-1','J','Energieberater prüfen gemeinsam mit Ihnen Heizung, Fenster und Stromverbrauch. Sie erhalten konkrete Vorschläge, wie Sie Kosten und Energieverbrauch senken können.',0,NULL,9),
('pruefung-01-teil3-q-1-K','pruefung-01-teil3-q-1','K','Jeden Freitag kochen Menschen aus dem Viertel ein gemeinsames Abendessen. Die Zutaten werden nach Möglichkeit gerettet oder regional eingekauft. Neue Gäste sind willkommen.',0,NULL,10),
('pruefung-01-teil3-q-1-L','pruefung-01-teil3-q-1','L','In zwei Workshops üben Sie Anschreiben, Lebenslauf und Vorstellungsgespräch. Das Angebot richtet sich an Arbeitssuchende und findet vormittags statt.',0,NULL,11),
('pruefung-01-teil3-q-1-X','pruefung-01-teil3-q-1','X','Für diese Situation gibt es in den Anzeigen kein geeignetes Angebot.',0,NULL,12),
('pruefung-01-teil3-q-2-A','pruefung-01-teil3-q-2','A','Jeden zweiten Samstag helfen Fachleute und Freiwillige beim Reparieren von kleinen Elektrogeräten. Bitte bringen Sie das Gerät und, wenn möglich, eine Beschreibung des Problems mit. Materialkosten werden berechnet.',0,NULL,0),
