('pruefung-02-teil2-q-1-A','pruefung-02-teil2-q-1','A','Die wöchentliche Arbeitszeit vollständig zu verkürzen.',0,NULL,0),
('pruefung-02-teil2-q-1-B','pruefung-02-teil2-q-1','B','Eine bessere Organisation bei gleichbleibender Erreichbarkeit zu prüfen.',0,NULL,1),
('pruefung-02-teil2-q-1-C','pruefung-02-teil2-q-1','C','Den Kundendienst nur noch an vier Tagen zu öffnen.',0,NULL,2),
('pruefung-02-teil2-q-2-A','pruefung-02-teil2-q-2','A','Damit die Teams ihre Aufgaben effizienter planen konnten.',0,NULL,0),
('pruefung-02-teil2-q-2-B','pruefung-02-teil2-q-2','B','Weil persönliche Gespräche grundsätzlich verboten wurden.',0,NULL,1),
('pruefung-02-teil2-q-2-C','pruefung-02-teil2-q-2','C','Damit die Geschäftsleitung alle Gespräche aufzeichnen konnte.',0,NULL,2),
('pruefung-02-teil2-q-3-A','pruefung-02-teil2-q-3','A','Alle Beschäftigten arbeiteten am freien Tag von zu Hause.',0,NULL,0),
('pruefung-02-teil2-q-3-B','pruefung-02-teil2-q-3','B','Die Kunden wurden nur noch per E-Mail informiert.',0,NULL,1),
('pruefung-02-teil2-q-3-C','pruefung-02-teil2-q-3','C','Die Mitarbeiter wechselten sich im Kundendienst ab.',0,NULL,2),
('pruefung-02-teil2-q-4-A','pruefung-02-teil2-q-4','A','Die Produktivität blieb stabil und kurzfristige Krankmeldungen gingen leicht zurück.',0,NULL,0),
('pruefung-02-teil2-q-4-B','pruefung-02-teil2-q-4','B','Alle Abteilungen mussten zusätzliches Personal einstellen.',0,NULL,1),
('pruefung-02-teil2-q-4-C','pruefung-02-teil2-q-4','C','Die Kunden konnten das Unternehmen nicht mehr erreichen.',0,NULL,2),
('pruefung-02-teil2-q-5-A','pruefung-02-teil2-q-5','A','Das Modell eignet sich ohne Änderungen für jede Branche.',0,NULL,0),
('pruefung-02-teil2-q-5-B','pruefung-02-teil2-q-5','B','Abteilungen mit täglichem Publikumsverkehr brauchen andere Lösungen.',0,NULL,1),
('pruefung-02-teil2-q-5-C','pruefung-02-teil2-q-5','C','Die Vier-Tage-Woche darf nur von Führungskräften genutzt werden.',0,NULL,2),
('pruefung-02-teil3-q-1-A','pruefung-02-teil3-q-1','A','Der Abendkurs richtet sich an Beschäftigte, die Tabellen übersichtlich gestalten, Formeln nutzen und einfache Auswertungen erstellen möchten. Vorkenntnisse sind nicht erforderlich.',1,'Passende Anzeige.',0),
('pruefung-02-teil3-q-1-B','pruefung-02-teil3-q-1','B','In drei Terminen lernen Sie, Nachrichtenquellen zu prüfen, manipulierte Bilder zu erkennen und Ihre persönlichen Daten in sozialen Netzwerken besser zu schützen.',0,NULL,1),
('pruefung-02-teil3-q-1-C','pruefung-02-teil3-q-1','C','Junge Beschäftigte treffen sich monatlich mit erfahrenen Fachkräften aus ihrer Branche. Im Mittelpunkt stehen berufliche Entscheidungen, Kommunikation und der Aufbau eines Netzwerks.',0,NULL,2),
('pruefung-02-teil3-q-1-D','pruefung-02-teil3-q-1','D','Flexible Arbeitsplätze, Besprechungsräume und schnelles Internet – tageweise oder monatlich buchbar. Ideal für Selbstständige und Beschäftigte, die nicht jeden Tag im Homeoffice arbeiten möchten.',0,NULL,3),
('pruefung-02-teil3-q-1-E','pruefung-02-teil3-q-1','E','Physiotherapeutinnen zeigen Übungen für Nacken, Schultern und Rücken. Der Kurs richtet sich an Personen, die lange am Schreibtisch sitzen.',0,NULL,4),
