INSERT OR IGNORE INTO reading_options (id,question_id,code,text,is_correct,explanation,order_index) VALUES
('teil2-02-teil2-q-4-B','teil2-02-teil2-q-4','B','Alle Abteilungen mussten zusätzliches Personal einstellen.',0,NULL,1),
('teil2-02-teil2-q-4-C','teil2-02-teil2-q-4','C','Die Kunden konnten das Unternehmen nicht mehr erreichen.',0,NULL,2),
('teil2-02-teil2-q-5-A','teil2-02-teil2-q-5','A','Das Modell eignet sich ohne Änderungen für jede Branche.',0,NULL,0),
('teil2-02-teil2-q-5-B','teil2-02-teil2-q-5','B','Abteilungen mit täglichem Publikumsverkehr brauchen andere Lösungen.',0,NULL,1),
('teil2-02-teil2-q-5-C','teil2-02-teil2-q-5','C','Die Vier-Tage-Woche darf nur von Führungskräften genutzt werden.',0,NULL,2),
('teil3-01-teil3-q-1-A','teil3-01-teil3-q-1','A','Jeden zweiten Samstag helfen Fachleute und Freiwillige beim Reparieren von kleinen Elektrogeräten. Bitte bringen Sie das Gerät und, wenn möglich, eine Beschreibung des Problems mit. Materialkosten werden berechnet.',0,NULL,0),
('teil3-01-teil3-q-1-B','teil3-01-teil3-q-1','B','Unser Gemeinschaftsgarten nimmt neue Mitglieder auf. Wer regelmäßig mitarbeiten möchte, kann ein eigenes Beet pflegen oder bei der Bewässerung helfen. Treffen: Mittwoch ab 17 Uhr.',0,NULL,1),
('teil3-01-teil3-q-1-C','teil3-01-teil3-q-1','C','In diesem Abendkurs lernen Sie, Bremsen einzustellen, Reifen zu wechseln und eine Kette zu reinigen. Eigenes Fahrrad und Grundwerkzeug können mitgebracht werden.',1,'Passende Anzeige.',2),
('teil3-01-teil3-q-1-D','teil3-01-teil3-q-1','D','Ein vierwöchiger Kurs zeigt, wie man mit regionalen Produkten, wenig Energie und kreativen Resterezepten kocht. Der Kurs ist für Anfänger geeignet.',0,NULL,3),
('teil3-01-teil3-q-1-E','teil3-01-teil3-q-1','E','Unser Schlaflabor untersucht Schlafstörungen und bietet individuelle Beratung nach ärztlicher Überweisung. Termine nach Vereinbarung.',0,NULL,4),
('teil3-01-teil3-q-1-F','teil3-01-teil3-q-1','F','Gut erhaltene Kinderkleidung, Kinderwagen und Spielzeug wechseln bei uns den Besitzer. Familien können Verkaufszeiten online reservieren und nicht verkaufte Ware wieder abholen.',0,NULL,5),
('teil3-01-teil3-q-1-G','teil3-01-teil3-q-1','G','Mit unserem Carsharing-Angebot stehen mehrere Fahrzeuge an festen Stationen bereit. Abgerechnet wird nach Zeit und gefahrenen Kilometern. Die Registrierung erfolgt über eine App.',0,NULL,6),
('teil3-01-teil3-q-1-H','teil3-01-teil3-q-1','H','Bei einem kostenlosen Spaziergang durch den Stadtpark erklärt eine Biologin, welche Vögel dort leben und wie man sie erkennt. Ferngläser können ausgeliehen werden.',0,NULL,7),
('teil3-01-teil3-q-1-I','teil3-01-teil3-q-1','I','Sie möchten regelmäßig Deutsch sprechen? Unser Tandemprogramm bringt Lernende mit deutschsprachigen Freiwilligen zusammen. Die Treffen finden in Cafés oder online statt.',0,NULL,8),
('teil3-01-teil3-q-1-J','teil3-01-teil3-q-1','J','Energieberater prüfen gemeinsam mit Ihnen Heizung, Fenster und Stromverbrauch. Sie erhalten konkrete Vorschläge, wie Sie Kosten und Energieverbrauch senken können.',0,NULL,9),
('teil3-01-teil3-q-1-K','teil3-01-teil3-q-1','K','Jeden Freitag kochen Menschen aus dem Viertel ein gemeinsames Abendessen. Die Zutaten werden nach Möglichkeit gerettet oder regional eingekauft. Neue Gäste sind willkommen.',0,NULL,10),
('teil3-01-teil3-q-1-L','teil3-01-teil3-q-1','L','In zwei Workshops üben Sie Anschreiben, Lebenslauf und Vorstellungsgespräch. Das Angebot richtet sich an Arbeitssuchende und findet vormittags statt.',0,NULL,11),
('teil3-01-teil3-q-1-X','teil3-01-teil3-q-1','X','Für diese Situation gibt es in den Anzeigen kein geeignetes Angebot.',0,NULL,12),
